-- StudyTrack / 01_schema.sql
-- DDL предметной модели «Учёт учебных заданий и результатов».
-- Идентификаторы — GENERATED BY DEFAULT AS IDENTITY (PostgreSQL).
-- Все FK имеют явное поведение ON DELETE; история не удаляется каскадно.

\set ON_ERROR_STOP on

BEGIN;

-- ---------------------------------------------------------------------------
-- 1. Пользователи (преподаватели, студенты, администратор)
-- ---------------------------------------------------------------------------
CREATE TABLE users (
    id            integer     GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    full_name     text        NOT NULL,
    email         text        NOT NULL,
    role          text        NOT NULL,
    login         text        NOT NULL,
    password_hash text        NOT NULL,
    is_active     boolean     NOT NULL DEFAULT true,
    created_at    timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT users_full_name_check CHECK (length(btrim(full_name)) >= 2),
    CONSTRAINT users_email_format_check CHECK (position('@' IN email) > 1),
    CONSTRAINT users_role_check CHECK (role IN ('student', 'teacher', 'admin')),
    CONSTRAINT users_login_format_check CHECK (login ~ '^[a-z0-9_.]{3,32}$'),
    CONSTRAINT users_email_key UNIQUE (email),
    CONSTRAINT users_login_key UNIQUE (login)
);

COMMENT ON TABLE users IS 'Учебные пользователи: преподаватели, студенты, администратор.';
COMMENT ON COLUMN users.role IS 'Предметная роль: student | teacher | admin.';
COMMENT ON COLUMN users.login IS 'Логин для входа в приложение (уникален, только [a-z0-9_.]).';
COMMENT ON COLUMN users.password_hash IS 'scrypt-хеш пароля формата scrypt$N$r$p$salt_b64$hash_b64. Открытый пароль не хранится.';

-- ---------------------------------------------------------------------------
-- 2. Категории курсов (иерархия через self-FK parent_id)
-- ---------------------------------------------------------------------------
CREATE TABLE course_categories (
    id         integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    parent_id  integer,
    title      text    NOT NULL,
    slug       text    NOT NULL,

    CONSTRAINT course_categories_title_check CHECK (length(btrim(title)) >= 2),
    CONSTRAINT course_categories_slug_check CHECK (slug ~ '^[a-z0-9-]+$'),
    CONSTRAINT course_categories_slug_key UNIQUE (slug),
    CONSTRAINT course_categories_parent_fk
        FOREIGN KEY (parent_id) REFERENCES course_categories (id) ON DELETE RESTRICT,
    -- запрет самоссылки (цикл глубже одного узла дополнительно проверяется рекурсивным запросом)
    CONSTRAINT course_categories_no_self_parent CHECK (parent_id IS NULL OR parent_id <> id)
);

COMMENT ON TABLE course_categories IS 'Иерархический справочник категорий курсов (ИТ → программирование → веб).';

-- ---------------------------------------------------------------------------
-- 3. Курсы
-- ---------------------------------------------------------------------------
CREATE TABLE courses (
    id           integer     GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    category_id  integer     NOT NULL,
    teacher_id   integer     NOT NULL,
    code         text        NOT NULL,
    title        text        NOT NULL,
    description  text        NOT NULL DEFAULT '',
    status       text        NOT NULL DEFAULT 'draft',
    created_at   timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT courses_code_key UNIQUE (code),
    CONSTRAINT courses_title_check CHECK (length(btrim(title)) >= 2),
    CONSTRAINT courses_status_check CHECK (status IN ('draft', 'active', 'archived')),
    CONSTRAINT courses_category_fk
        FOREIGN KEY (category_id) REFERENCES course_categories (id) ON DELETE RESTRICT,
    CONSTRAINT courses_teacher_fk
        FOREIGN KEY (teacher_id) REFERENCES users (id) ON DELETE RESTRICT
);

COMMENT ON TABLE courses IS 'Курсы. Удаление категории/преподавателя запрещено, пока есть курсы.';

-- ---------------------------------------------------------------------------
-- 4. Зачисления (M:N между студентами и курсами)
-- ---------------------------------------------------------------------------
CREATE TABLE enrollments (
    id           integer     GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    course_id    integer     NOT NULL,
    student_id   integer     NOT NULL,
    status       text        NOT NULL DEFAULT 'active',
    enrolled_at  timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT enrollments_status_check CHECK (status IN ('active', 'completed', 'dropped')),
    CONSTRAINT enrollments_course_student_key UNIQUE (course_id, student_id),
    CONSTRAINT enrollments_course_fk
        FOREIGN KEY (course_id) REFERENCES courses (id) ON DELETE RESTRICT,
    CONSTRAINT enrollments_student_fk
        FOREIGN KEY (student_id) REFERENCES users (id) ON DELETE RESTRICT
);

COMMENT ON TABLE enrollments IS 'Зачисления студента на курс; одна пара курс-студент уникальна.';

-- ---------------------------------------------------------------------------
-- 5. Задания
-- ---------------------------------------------------------------------------
CREATE TABLE assignments (
    id               integer      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    course_id        integer      NOT NULL,
    title            text         NOT NULL,
    description      text         NOT NULL DEFAULT '',
    due_at           timestamptz  NOT NULL,
    max_score        numeric(6,2) NOT NULL,
    -- дополнительные характеристики задания (submission_format, expected_minutes, allow_revision)
    extra            jsonb        NOT NULL DEFAULT '{}'::jsonb,
    -- вычисляемый индексируемый столбец: числовой атрибут из JSONB
    expected_minutes integer      GENERATED ALWAYS AS ((extra ->> 'expected_minutes')::integer) STORED,
    -- полнотекстовый вектор по названию и описанию задания
    search_vector    tsvector     GENERATED ALWAYS AS (
                         to_tsvector('russian', coalesce(title, '') || ' ' || coalesce(description, ''))
                     ) STORED,
    created_at       timestamptz  NOT NULL DEFAULT now(),

    CONSTRAINT assignments_title_check CHECK (length(btrim(title)) >= 3),
    CONSTRAINT assignments_max_score_check CHECK (max_score > 0),
    CONSTRAINT assignments_extra_object_check CHECK (jsonb_typeof(extra) = 'object'),
    -- диапазон expected_minutes: от 5 минут до 7 суток; отсутствие ключа => NULL
    CONSTRAINT assignments_expected_minutes_range_check
        CHECK (expected_minutes IS NULL OR expected_minutes BETWEEN 5 AND 10080),
    CONSTRAINT assignments_extra_types_check CHECK (
        (NOT extra ? 'submission_format') OR jsonb_typeof(extra -> 'submission_format') = 'string'
    ),
    CONSTRAINT assignments_extra_allow_revision_check CHECK (
        (NOT extra ? 'allow_revision') OR jsonb_typeof(extra -> 'allow_revision') = 'boolean'
    ),
    CONSTRAINT assignments_extra_expected_minutes_type_check CHECK (
        (NOT extra ? 'expected_minutes') OR jsonb_typeof(extra -> 'expected_minutes') = 'number'
    ),
    CONSTRAINT assignments_course_fk
        FOREIGN KEY (course_id) REFERENCES courses (id) ON DELETE RESTRICT
);

COMMENT ON TABLE assignments IS 'Задания курса: срок, максимальный балл, JSONB-параметры.';
COMMENT ON COLUMN assignments.expected_minutes IS 'Вычисляемый столбец из extra->>expected_minutes (GENERATED STORED).';
COMMENT ON COLUMN assignments.search_vector IS 'Полнотекстовый вектор (russian) для GIN-индекса.';

-- ---------------------------------------------------------------------------
-- 6. Версии работ (автор = студент, номер версии уникален в паре студент-задание)
-- ---------------------------------------------------------------------------
CREATE TABLE submission_versions (
    id            integer     GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    assignment_id integer     NOT NULL,
    student_id    integer     NOT NULL,
    version_no    integer     NOT NULL,
    body          text        NOT NULL,
    submitted_at  timestamptz NOT NULL DEFAULT now(),
    is_late       boolean     NOT NULL DEFAULT false,

    CONSTRAINT submission_versions_version_no_check CHECK (version_no > 0),
    CONSTRAINT submission_versions_body_check CHECK (length(btrim(body)) > 0),
    CONSTRAINT submission_versions_unique_version UNIQUE (assignment_id, student_id, version_no),
    CONSTRAINT submission_versions_assignment_fk
        FOREIGN KEY (assignment_id) REFERENCES assignments (id) ON DELETE RESTRICT,
    CONSTRAINT submission_versions_student_fk
        FOREIGN KEY (student_id) REFERENCES users (id) ON DELETE RESTRICT
);

COMMENT ON TABLE submission_versions IS
    'Версии сданной работы. Номер версии уникален внутри пары студент-задание.';

-- ---------------------------------------------------------------------------
-- 7. Оценки (одна актуальная оценка на версию, история исправлений — grade_history)
-- ---------------------------------------------------------------------------
CREATE TABLE grades (
    id          integer      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version_id  integer      NOT NULL,
    graded_by   integer      NOT NULL,
    score       numeric(6,2) NOT NULL,
    comment     text,
    graded_at   timestamptz  NOT NULL DEFAULT now(),

    CONSTRAINT grades_version_key UNIQUE (version_id),
    CONSTRAINT grades_score_nonnegative_check CHECK (score >= 0),
    CONSTRAINT grades_version_fk
        FOREIGN KEY (version_id) REFERENCES submission_versions (id) ON DELETE RESTRICT,
    CONSTRAINT grades_grader_fk
        FOREIGN KEY (graded_by) REFERENCES users (id) ON DELETE RESTRICT
);

COMMENT ON TABLE grades IS
    'Оценка конкретной версии. Верхняя граница (max_score задания) проверяется триггером/процедурой.';

-- ---------------------------------------------------------------------------
-- 8. История изменений оценок (пишется триггером)
-- ---------------------------------------------------------------------------
CREATE TABLE grade_history (
    id          integer      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    grade_id    integer,
    version_id  integer,
    old_score   numeric(6,2),
    new_score   numeric(6,2) NOT NULL,
    action      text         NOT NULL,
    changed_by  integer,
    changed_at  timestamptz  NOT NULL DEFAULT now(),
    comment     text,

    CONSTRAINT grade_history_action_check CHECK (action IN ('INSERT', 'UPDATE')),
    CONSTRAINT grade_history_grade_fk
        FOREIGN KEY (grade_id) REFERENCES grades (id) ON DELETE SET NULL,
    CONSTRAINT grade_history_version_fk
        FOREIGN KEY (version_id) REFERENCES submission_versions (id) ON DELETE SET NULL,
    CONSTRAINT grade_history_changed_by_fk
        FOREIGN KEY (changed_by) REFERENCES users (id) ON DELETE SET NULL
);

COMMENT ON TABLE grade_history IS
    'Неизменяемая история выставления/исправления оценок (заполняется триггером).';

-- ---------------------------------------------------------------------------
-- 9. Журнал действий администратора (пишется админскими процедурами)
-- ---------------------------------------------------------------------------
CREATE TABLE admin_audit_log (
    id          bigint      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    actor_id    integer,
    action      text        NOT NULL,
    entity      text        NOT NULL,
    entity_id   integer,
    details     jsonb       NOT NULL DEFAULT '{}'::jsonb,
    created_at  timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT admin_audit_log_entity_check
        CHECK (entity IN ('user', 'course', 'assignment', 'category', 'enrollment')),
    CONSTRAINT admin_audit_log_actor_fk
        FOREIGN KEY (actor_id) REFERENCES users (id) ON DELETE SET NULL
);

COMMENT ON TABLE admin_audit_log IS
    'Журнал административных операций: кто, что и когда изменил (неизменяемый).';
COMMENT ON COLUMN admin_audit_log.action IS
    'Код операции: create_user, set_role, toggle_user, upsert_course, archive_course, ...';

COMMIT;
